+{"version":3,"sources":["/workspace/repo/src/__tests__/controller.test.tsx"],"sourcesContent":["import React from 'react';\nimport {\n  act as actComponent,\n  fireEvent,\n  render,\n  screen,\n  waitFor,\n  waitForElementToBeRemoved,\n} from '@testing-library/react';\n\nimport { Controller } from '../controller';\nimport type {\n  ControllerRenderProps,\n  FieldValues,\n  ValidateResult,\n} from '../types';\nimport { useFieldArray } from '../useFieldArray';\nimport { useForm } from '../useForm';\nimport { FormProvider } from '../useFormContext';\nimport { useWatch } from '../useWatch';\nimport noop from '../utils/noop';\n\nfunction Input<TFieldValues extends FieldValues>({\n  onChange,\n  onBlur,\n  placeholder,\n}: Pick<ControllerRenderProps<TFieldValues>, 'onChange' | 'onBlur'> & {\n  placeholder?: string;\n}) {\n  return (\n    <input\n      placeholder={placeholder}\n      onChange={() => onChange(1)}\n      onBlur={() => onBlur()}\n    />\n  );\n}\n\ndescribe('Controller', () => {\n  it('should render correctly with as with string', () => {\n    const Component = () => {\n      const { control } = useForm();\n      return (\n        <Controller\n          defaultValue=\"\"\n          name=\"test\"\n          render={({ field }) => <input {...field} />}\n          control={control}\n        />\n      );\n    };\n\n    render(<Component />);\n\n    const input = screen.getByRole('textbox') as HTMLInputElement;\n\n    expect(input).toBeVisible();\n    expect(input.name).toBe('test');\n  });\n\n  it('should render correctly with as with component', () => {\n    const Component = () => {\n      const { control } = useForm();\n      return (\n        <Controller\n          defaultValue=\"\"\n          name=\"test\"\n          render={({ field }) => <input {...field} />}\n          control={control}\n        />\n      );\n    };\n\n    render(<Component />);\n\n    const input = screen.getByRole('textbox') as HTMLInputElement;\n\n    expect(input).toBeVisible();\n    expect(input?.name).toBe('test');\n  });\n\n  it('should reset value', async () => {\n    const Component = () => {\n      const { reset, control } = useForm();\n\n      return (\n        <>\n          <Controller\n            defaultValue=\"default\"\n            name=\"test\"\n            render={({ field }) => <input {...field} />}\n            control={control}\n          />\n          <button\n            type=\"button\"\n            onClick={() =>\n              reset({\n                test: 'default',\n              })\n            }\n          >\n            reset\n          </button>\n        </>\n      );\n    };\n\n    render(<Component />);\n\n    fireEvent.input(screen.getByRole('textbox'), { target: { value: 'test' } });\n    expect(screen.getByRole('textbox')).toHaveValue('test');\n\n    fireEvent.click(screen.getByRole('button', { name: /reset/i }));\n    expect(screen.getByRole('textbox')).toHaveValue('default');\n  });\n\n  it('should set defaultValue to value props when input was reset', () => {\n    const Component = () => {\n      const { reset, control } = useForm<{\n        test: string;\n      }>();\n\n      React.useEffect(() => {\n        reset({ test: 'default' });\n      }, [reset]);\n\n      return (\n        <Controller\n          defaultValue=\"\"\n          name=\"test\"\n          render={({ field }) => <input {...field} />}\n          control={control}\n        />\n      );\n    };\n\n    render(<Component />);\n\n    expect(screen.getByRole('textbox')).toHaveValue('default');\n  });\n\n  it('should render when registered field values are updated', () => {\n    const Component = () => {\n      const { control } = useForm();\n      return (\n        <Controller\n          defaultValue=\"\"\n          name=\"test\"\n          render={({ field }) => <input {...field} />}\n          control={control}\n        />\n      );\n    };\n\n    render(<Component />);\n\n    fireEvent.input(screen.getByRole('textbox'), { target: { value: 'test' } });\n\n    expect(screen.getByRole('textbox')).toHaveValue('test');\n  });\n\n  it(\"should trigger component's onChange method and invoke setValue method\", () => {\n    let fieldValues: unknown;\n    const Component = () => {\n      const { control, getValues } = useForm();\n\n      return (\n        <>\n          <Controller\n            defaultValue=\"\"\n            name=\"test\"\n            render={({ field }) => <input {...field} />}\n            control={control}\n          />\n          <button onClick={() => (fieldValues = getValues())}>getValues</button>\n        </>\n      );\n    };\n\n    render(<Component />);\n\n    fireEvent.input(screen.getByRole('textbox'), {\n      target: { value: 'test' },\n    });\n\n    fireEvent.click(screen.getByRole('button', { name: /getValues/ }));\n\n    expect(fieldValues).toEqual({ test: 'test' });\n  });\n\n  it(\"should trigger component's onChange method and invoke trigger method\", async () => {\n    let errors: any;\n    const Component = () => {\n      const { control, ...rest } = useForm({ mode: 'onChange' });\n\n      errors = rest.formState.errors;\n\n      return (\n        <Controller\n          defaultValue=\"test\"\n          name=\"test\"\n          render={({ field }) => <input {...field} />}\n          control={control}\n          rules={{ required: true }}\n        />\n      );\n    };\n\n    render(<Component />);\n\n    fireEvent.input(screen.getByRole('textbox'), {\n      target: { value: '' },\n    });\n\n    await waitFor(() => expect(errors.test).toBeDefined());\n  });\n\n  it(\"should trigger component's onBlur method and invoke trigger method\", async () => {\n    let errors: any;\n    const Component = () => {\n      const { control, ...rest } = useForm({ mode: 'onBlur' });\n\n      errors = rest.formState.errors;\n\n      return (\n        <Controller\n          defaultValue=\"\"\n          name=\"test\"\n          render={({ field }) => <input {...field} />}\n          control={control}\n          rules={{ required: true }}\n        />\n      );\n    };\n\n    render(<Component />);\n\n    fireEvent.blur(screen.getByRole('textbox'), {\n      target: { value: '' },\n    });\n\n    await waitFor(() => expect(errors.test).toBeDefined());\n  });\n\n  it('should set field to formState.touchedFields', async () => {\n    let touched: any;\n    const Component = () => {\n      const { control, formState } = useForm({ mode: 'onBlur' });\n\n      touched = formState.touchedFields;\n\n      return (\n        <Controller\n          defaultValue=\"\"\n          name=\"test\"\n          render={({ field }) => <input {...field} />}\n          control={control}\n        />\n      );\n    };\n\n    render(<Component />);\n\n    fireEvent.blur(screen.getByRole('textbox'));\n\n    expect(touched).toEqual({ test: true });\n  });\n\n  it('should set field to formState validatingFields and render field isValidating state', async () => {\n    jest.useFakeTimers();\n\n    const getValidateMock: (timeout: number) => Promise<ValidateResult> = (\n      timeout: number,\n    ) => {\n      return new Promise((resolve) => {\n        setTimeout(() => {\n          resolve(true);\n        }, timeout);\n      });\n    };\n\n    let validatingFields: any;\n    const Component = () => {\n      const { control, formState } = useForm({ mode: 'onBlur' });\n\n      validatingFields = formState.validatingFields;\n\n      return (\n        <Controller\n          defaultValue=\"\"\n          name=\"test\"\n          render={({ field, fieldState }) => (\n            <>\n              <div>isValidating: {String(fieldState.isValidating)}</div>\n              <input {...field} />\n            </>\n          )}\n          control={control}\n          rules={{\n            validate: () => getValidateMock(1000),\n          }}\n        />\n      );\n    };\n\n    render(<Component />);\n\n    expect(validatingFields).toEqual({});\n    expect(screen.getByText('isValidating: false')).toBeVisible();\n\n    fireEvent.blur(screen.getByRole('textbox'));\n\n    expect(validatingFields).toEqual({ test: true });\n    expect(screen.getByText('isValidating: true')).toBeVisible();\n\n    await actComponent(async () => {\n      jest.advanceTimersByTime(1100);\n    });\n\n    expect(validatingFields).toEqual({});\n    expect(screen.getByText('isValidating: false')).toBeVisible();\n  });\n\n  it('should call trigger method when re-validate mode is onBlur with blur event', async () => {\n    const Component = () => {\n      const {\n        handleSubmit,\n        control,\n        formState: { errors },\n      } = useForm({\n        reValidateMode: 'onBlur',\n      });\n\n      return (\n        <form onSubmit={handleSubmit(noop)}>\n          <Controller\n            defaultValue=\"\"\n            name=\"test\"\n            render={({ field }) => <input {...field} />}\n            control={control}\n            rules={{ required: true }}\n          />\n          {errors.test && <span role=\"alert\">required</span>}\n          <button>submit</button>\n        </form>\n      );\n    };\n    render(<Component />);\n\n    fireEvent.blur(screen.getByRole('textbox'), {\n      target: {\n        value: '',\n      },\n    });\n\n    expect(screen.queryByRole('alert')).not.toBeInTheDocument();\n\n    fireEvent.submit(screen.getByRole('button'));\n\n    fireEvent.input(screen.getByRole('textbox'), {\n      target: {\n        value: 'test',\n      },\n    });\n\n    expect(await screen.findByRole('alert')).toBeVisible();\n\n    fireEvent.blur(screen.getByRole('textbox'), {\n      target: {\n        value: 'test',\n      },\n    });\n\n    await waitForElementToBeRemoved(screen.queryByRole('alert'));\n  });\n\n  it('should invoke custom event named method', () => {\n    let fieldValues: any;\n    const Component = () => {\n      const { control, getValues } = useForm();\n      return (\n        <>\n          <Controller\n            defaultValue=\"\"\n            name=\"test\"\n     