pe: 'test',\n          },\n        });\n      });\n    });\n\n    it('should validate all fields when pass with undefined', async () => {\n      const resolver = async (data: any) => {\n        return {\n          values: data,\n          errors: {\n            test1: {\n              type: 'test1',\n            },\n            test: {\n              type: 'test',\n            },\n          },\n        };\n      };\n\n      const { result } = renderHook(() =>\n        useForm<{ test1: string; test: string }>({\n          mode: VALIDATION_MODE.onChange,\n          resolver,\n        }),\n      );\n\n      result.current.formState.errors;\n\n      result.current.register('test', { required: true });\n      result.current.register('test1', { required: true });\n\n      await act(async () => {\n        await result.current.trigger();\n      });\n\n      expect(result.current.formState.errors).toEqual({\n        test1: {\n          type: 'test1',\n        },\n        test: {\n          type: 'test',\n        },\n      });\n    });\n\n    it('should update isValid with validation result at form level', async () => {\n      const App = () => {\n        const {\n          register,\n          formState: { isValid },\n          trigger,\n        } = useForm<{ test: string; test1: string }>({\n          defaultValues: {\n            test: '',\n          },\n          resolver: async (data) => {\n            if (data.test && data.test1) {\n              return {\n                errors: {},\n                values: {},\n              };\n            } else {\n              return {\n                errors: {\n                  test: {\n                    message: 'test',\n                    type: 'test',\n                  },\n                },\n                values: {},\n              };\n            }\n          },\n        });\n\n        return (\n          <div>\n            {isValid ? 'yes' : 'no'}\n            <input {...register('test')} />\n            <input {...register('test1')} />\n            <button\n              onClick={() => {\n                trigger('test');\n              }}\n            >\n              trigger1\n            </button>\n            <button\n              onClick={() => {\n                trigger('test1');\n              }}\n            >\n              trigger2\n            </button>\n          </div>\n        );\n      };\n\n      render(<App />);\n\n      fireEvent.change(screen.getAllByRole('textbox')[0], {\n        target: {\n          value: 'test',\n        },\n      });\n\n      fireEvent.click(screen.getByRole('button', { name: 'trigger1' }));\n\n      expect(await screen.findByText('no')).toBeVisible();\n\n      fireEvent.change(screen.getAllByRole('textbox')[1], {\n        target: {\n          value: 'test',\n        },\n      });\n\n      fireEvent.click(screen.getByRole('button', { name: 'trigger2' }));\n\n      expect(await screen.findByText('yes')).toBeVisible();\n    });\n\n    it('should update isValid for the entire useForm scope', async () => {\n      const InputA = () => {\n        const { isValid } = useFormState({ name: 'name' });\n\n        return <p>{isValid ? 'test: valid' : 'test: invalid'}</p>;\n      };\n\n      const InputB = () => {\n        const { isValid } = useFormState({ name: 'email' });\n\n        return <p>{isValid ? 'test1: valid' : 'test1: invalid'}</p>;\n      };\n\n      function App() {\n        const methods = useForm({\n          resolver: async (data) => {\n            if (data.test && data.test1) {\n              return {\n                errors: {},\n                values: {},\n              };\n            } else {\n              return {\n                errors: {\n                  test: {\n                    message: 'test',\n                    type: 'test',\n                  },\n                },\n                values: {},\n              };\n            }\n          },\n          mode: 'onChange',\n        });\n\n        return (\n      