);\n\n  it('should only react to formState changes it subscribes to', async () => {\n    const callbackFn = jest.fn();\n\n    const App = () => {\n      const { register, subscribe, control } = useForm({\n        defaultValues: {\n          first: '',\n          sec: '',\n        },\n      });\n\n      const fieldFormState = useFormState({\n        name: 'first',\n        control,\n      });\n\n      fieldFormState.touchedFields;\n\n      React.useEffect(() => {\n        return subscribe({\n          formState: {\n            values: true,\n          },\n          name: 'sec',\n          callback: callbackFn,\n        });\n      }, [subscribe]);\n\n      return (\n        <form>\n          <input {...register('first')} />\n          <input {...register('sec')} />\n        </form>\n      );\n    };\n    render(<App />);\n\n    fireEvent.blur(screen.getAllByRole('textbox')[1]);\n\n    fireEvent.input(screen.getAllByRole('textbox')[1], {\n      target: { value: 'test' },\n    });\n\n    fireEvent.input(screen.getAllByRole('textbox')[1], {\n      target: { value: 'test2' },\n    });\n\n    expect(callbackFn).toHaveBeenCalledTimes(2);\n  });\n\n  it('should allow subscribing to submit state updates', async () => {\n    const callbackFn = jest.fn();\n\n    const App = () => {\n      const { handleSubmit, subscribe } = useForm();\n\n      React.useEffect(() => {\n        return subscribe({\n          formState: {\n            isSubmitted: true,\n            submitCount: true,\n          },\n          callback: callbackFn,\n        });\n      }, [subscribe]);\n\n      return (\n        <form onSubmit={handleSubmit(() => undefined)}>\n          <button type=\"submit\">Submit</button>\n        </form>\n      );\n    };\n\n    render(<App />);\n\n    fireEvent.click(screen.getByRole('button', { name: 'Submit' }));\n\n    await waitFor(() =>\n      expect(callbackFn).toHaveBeenCalledWith(\n        expect.objectContaining({\n          isSubmitted: true,\n          submitCount: 1