+{"version":3,"sources":["/workspace/repo/src/__tests__/useFieldArray.test.tsx"],"sourcesContent":["import React, { useState } from 'react';\nimport {\n  act,\n  fireEvent,\n  render,\n  renderHook,\n  screen,\n  waitFor,\n} from '@testing-library/react';\n\nimport { Controller } from '../controller';\nimport type {\n  Control,\n  FieldValues,\n  SubmitHandler,\n  UseFieldArrayProps,\n  UseFormRegister,\n  UseFormReturn,\n} from '../types';\nimport { useFieldArray } from '../useFieldArray';\nimport { useForm } from '../useForm';\nimport { FormProvider } from '../useFormContext';\nimport { useFormState } from '../useFormState';\nimport noop from '../utils/noop';\n\nlet i = 0;\n\njest.mock('../logic/generateId', () => () => String(i++));\n\ndescribe('useFieldArray', () => {\n  beforeEach(() => {\n    i = 0;\n  });\n\n  describe('initialize', () => {\n    it('should return default fields value', () => {\n      const { result } = renderHook(() => {\n        const { control } = useForm();\n        return useFieldArray({\n          control,\n          name: 'test',\n        });\n      });\n\n      expect(result.current.fields).toEqual([]);\n    });\n\n    it('should populate default values into fields', () => {\n      const { result } = renderHook(() => {\n        const { control } = useForm({\n          defaultValues: { test: [{ test: '1' }, { test: '2' }] },\n        });\n        return useFieldArray({\n          control,\n          name: 'test',\n        });\n      });\n\n      expect(result.current.fields).toEqual([\n        { test: '1', id: '0' },\n        { test: '2', id: '1' },\n      ]);\n    });\n\n    it('should populate values into fields instead of defaultValues', () => {\n      const { result } = renderHook(() => {\n        const { control } = useForm({\n          defaultValues: { test: [{ test: '3' }, { test: '21' }] },\n          values: { test: [{ test: '1' }, { test: '3' }, { test: '55' }] },\n        });\n        return useFieldArray({\n          control,\n          name: 'test',\n        });\n      });\n\n      expect(result.current.fields).toEqual([\n        { test: '1', id: '2' },\n        { test: '3', id: '3' },\n        { test: '55', id: '4' },\n      ]);\n    });\n\n    it('should render with FormProvider', () => {\n      const Provider = ({ children }: { children: React.ReactNode }) => {\n        const methods = useForm();\n        return <FormProvider {...methods}>{children}</FormProvider>;\n      };\n      expect(() =>\n        renderHook(() => useFieldArray({ name: 'test' }), {\n          wrapper: Provider,\n        }),\n      ).not.toThrow();\n    });\n  });\n\n  describe('with should unregister false', () => {\n    it('should still remain input value with toggle', () => {\n      const Component = () => {\n        const { register, control } = useForm<{\n          test: {\n            value: string;\n          }[];\n        }>();\n        const [show, setShow] = React.useState(true);\n        const { fields, append } = useFieldArray({\n          control,\n          name: 'test',\n        });\n\n        return (\n          <form>\n            {show &&\n              fields.map((field, i) => (\n                <input\n                  key={field.id}\n                  {...register(`test.${i}.value` as const)}\n                />\n              ))}\n            <button type=\"button\" onClick={() => append({ value: '' })}>\n              append\n            </button>\n            <button type=\"button\" onClick={() => setShow(!show)}>\n              toggle\n            </button>\n          </form>\n        );\n      };\n\n      render(<Component />);\n\n      fireEvent.click(screen.getByRole('button', { name: 'append' }));\n      expect(screen.getAllByRole('textbox').length).toEqual(1);\n      fireEvent.click(screen.getByRole('button', { name: 'toggle' }));\n      expect(screen.queryByRole('textbox')).not.toBeInTheDocument();\n      fireEvent.click(screen.getByRole('button', { name: 'toggle' }));\n      expect(screen.getAllByRole('textbox').length).toEqual(1);\n    });\n\n    it('should show errors during mount when mode is set to onChange', async () => {\n      const Component = () => {\n        const {\n          register,\n          control,\n          formState: { isValid, errors },\n        } = useForm<{ test: { value: string }[] }>({\n          defaultValues: {\n            test: [{ value: 'test' }],\n          },\n          resolver: async () => ({\n            values: {},\n            errors: {\n              test: [{ value: { message: 'wrong', type: 'test' } }],\n            },\n          }),\n          mode: 'onChange',\n        });\n        const { fields, append } = useFieldArray({ name: 'test', control });\n\n        return (\n          <form>\n            {fields.map((field, i) => (\n              <input key={field.id} {...register(`test.${i}.value` as const)} />\n            ))}\n            <button\n              type=\"button\"\n              onClick={() =>\n                append({\n                  value: 'test',\n                })\n              }\n            >\n              append\n            </button>\n\n            {!isValid && <p>not valid</p>}\n            {errors.test && <p>errors</p>}\n          </form>\n        );\n      };\n\n      render(<Component />);\n\n      expect(await screen.findByRole('textbox')).toBeVisible();\n      expect(await screen.findByText('not valid')).toBeVisible();\n    });\n\n    it('should retain input values during unmount', async () => {\n      type FormValues = {\n        test: { name: string }[];\n      };\n\n      const FieldArray = ({\n        control,\n        register,\n      }: {\n        control: Control<FormValues>;\n        register: UseFormRegister<FormValues>;\n      }) => {\n        const { fields } = useFieldArray({\n          control,\n          name: 'test',\n        });\n\n        return (\n          <div>\n            {fields.map((item, index) => {\n              return (\n                <div key={item.id}>\n                  <input {...register(`test.${index}.name`)} />\n                </div>\n              );\n            })}\n          </div>\n        );\n      };\n\n      const App = () => {\n        const [show, setShow] = React.useState(true);\n        const { control, register } = useForm({\n          shouldUnregister: false,\n          defaultValues: {\n            test: [{ name: 'test' }],\n          },\n        });\n\n        return (\n          <div>\n            {show && <FieldArray control={control} register={register} />}\n            <button type={'button'} onClick={() => setShow(!show)}>\n              toggle\n            </button>\n          </div>\n        );\n      };\n\n      render(<App />);\n\n      fireEvent.change(screen.getByRole('textbox'), {\n        target: { value: '12345' },\n      });\n\n      fireEvent.click(screen.getByRole('button'));\n\n      fireEvent.click(screen.getByRole('button'));\n\n      expect((screen.getByRole('textbox') as HTMLInputElement).value).toEqual(\n        '12345',\n      );\n    });\n  });\n\n  describe('with resolver', () => {\n    it('should provide updated form value each action', async () => {\n      let formData = {};\n      const Component = () => {\n        const {\n          register,\n          control,\n          formState: { isValid },\n        } = useForm<{\n          data: string;\n          test: { value: string }[];\n        }>({\n          resolver: (data) => {\n            formData = data;\n            return {\n              values: {},\n              errors: {},\n            };\n          },\n        });\n        const { fields, append } = useFieldArray({ name: 'test', control });\n\n        return (\n          <div>\n            <input {...register('data')} defaultValue=\"test\" />\n            {fields.map((field, i) => (\n              <input key={field.id} {...register(`test.${i}.value` as const)} />\n            ))}\n            <button onClick={() => append({ value: '' })}>append</button>\n            <span>{isValid && 'valid'}</span>\n          </div>\n        );\n      };\n\n      render(<Component />);\n\n      expect(await screen.findByText('valid')).toBeVisible();\n\n      fireEvent.click(screen.getByRole('button'));\n\n      expect(formData).toEqual({\n        data: 'test',\n        test: [{ value: '' }],\n      });\n    });\n\n    it('should provide correct form data with nested field array', async () => {\n      type FormValues = {\n        test: {\n          value: string;\n          nestedArray: {\n            value: string;\n          }[];\n        }[];\n      };\n\n      let formData: any = {};\n      const Nested = ({\n        index,\n        control,\n      }: {\n        control: Control<FormValues>;\n        index: number;\n      }) => {\n        const { fields, append } = useFieldArray<FormValues>({\n          name: `test.${index}.nestedArray` as const,\n          control,\n        });\n\n        return (\n          <div>\n            {fields.map((item, i) => (\n              <input\n                key={item.id}\n                {...control.register(\n                  `test.${index}.nestedArray.${i}.value` as const,\n                )}\n              />\n            ))}\n\n            <button type={'button'} onClick={() => append({ value: 'test' })}>\n              Append Nest\n            </button>\n          </div>\n        );\n      };\n\n      const Component = () => {\n        const {\n          register,\n          control,\n          formState: { isValid },\n        } = useForm<FormValues>({\n          resolver: (data) => {\n            formData = data;\n            return {\n              values: data,\n              errors: {},\n            };\n          },\n          mode: 'onChange',\n          defaultValues: {\n            test: [{ value: '1', nestedArray: [{ value: '2' }] }],\n          },\n        });\n        const { fields, remove } = useFieldArray({\n          name: 'test',\n          control,\n   