+{"version":3,"sources":["/workspace/repo/src/__tests__/watch.test.tsx"],"sourcesContent":["import React from 'react';\nimport { fireEvent, render, screen, waitFor } from '@testing-library/react';\n\nimport type { Control, UseFormReturn } from '../types';\nimport { useForm } from '../useForm';\nimport noop from '../utils/noop';\nimport { Watch } from '../watch';\n\ntype FormType = {\n  foo: string;\n  bar: string;\n  baz: {\n    qux: string;\n  };\n  quux: number;\n  fie: null;\n  foe: { qux: number[] };\n};\n\ndescribe('Watch', () => {\n  it('should render with default value in useForm', () => {\n    let watched;\n    const Component = () => {\n      const form = useForm<{ test: string }>({\n        defaultValues: { test: 'test' },\n      });\n      return (\n        <Watch\n          control={form.control}\n          render={(value) => {\n            watched = value;\n            return null;\n          }}\n        />\n      );\n    };\n    render(<Component />);\n\n    expect(watched).toEqual({ test: 'test' });\n  });\n\n  it('should render with default value for single input', () => {\n    let watched;\n    const Component = () => {\n      const form = useForm<{ test: string; test1: string }>({\n        defaultValues: {\n          test: 'test',\n          test1: 'test1',\n        },\n      });\n      return (\n        <Watch\n          control={form.control}\n          names=\"test\"\n          render={(value) => {\n            watched = value;\n            return null;\n          }}\n        />\n      );\n    };\n    render(<Component />);\n\n    expect(watched).toEqual('test');\n  });\n\n  it('should render with default values for array of inputs', () => {\n    let watched;\n    const Component = () => {\n      const form = useForm<{ test: string; test1: string }>({\n        defaultValues: {\n          test: 'test',\n          test1: 'test1',\n        },\n      });\n      return (\n        <Watch\n          control={form.control}\n          names={['test', 'test1']}\n          render={(value) => {\n            watched = value;\n            return null;\n          }}\n        />\n      );\n    };\n    render(<Component />);\n\n    expect(watched).toEqual(['test', 'test1']);\n  });\n\n  it('should render with own default value for single input', () => {\n    let watched;\n    const Component = () => {\n      const form = useForm<{ test: string; test1: string }>({});\n      return (\n        <Watch\n          control={form.control}\n          names=\"test\"\n          defaultValue=\"somevalue\"\n          render={(value) => {\n            watched = value;\n            return null;\n          }}\n        />\n      );\n    };\n    render(<Component />);\n\n    expect(watched).toEqual('somevalue');\n  });\n\n  it('should render with own default value for array of inputs', () => {\n    let watched;\n    const Component = () => {\n      const form = useForm<{ test: string; test1: string }>({});\n      return (\n        <Watch\n          control={form.control}\n          names={['test', 'test1']}\n          defaultValue={{ test: 'somevalue', test1: 'somevalue1' }}\n          render={(value) => {\n            watched = value;\n            return null;\n          }}\n        />\n      );\n    };\n    render(<Component />);\n\n    expect(watched).toEqual(['somevalue', 'somevalue1']);\n  });\n\n  it('should render with empty array when watch array fields and no default value', () => {\n    let watched;\n    const Component = () => {\n      const form = useForm<{ test: string }>();\n      return (\n        <Watch\n          control={form.control}\n          names={['test']}\n          render={(value) => {\n            watched = value;\n            return null;\n          }}\n        />\n      );\n    };\n    render(<Component />);\n\n    expect(watched).toEqual([undefined]);\n  });\n\n  it('should render with undefined when watch single field and no default value', () => {\n    let watched;\n    const Component = () => {\n      const form = useForm<{ test: string }>();\n      return (\n        <Watch\n          control={form.control}\n          names=\"test\"\n          render={(value) => {\n            watched = value;\n            return null;\n          }}\n        />\n      );\n    };\n    render(<Component />);\n\n    expect(watched).toEqual(undefined);\n  });\n\n  it('should subscribe to exact input change', () => {\n    const App = () => {\n      const { control, register } = useForm();\n\n      return (\n        <div>\n          <input {...register('test.0.data')} />\n          <Watch\n            control={control}\n            names=\"test\"\n            exact={true}\n            defaultValue=\"test\"\n            render={(value) => <p>{value}</p>}\n          />\n        </div>\n      );\n    };\n\n    render(<App />);\n\n    fireEvent.change(screen.getByRole('textbox'), {\n      target: {\n        value: '1234',\n      },\n    });\n\n    expect(screen.getByText('test')).toBeVisible();\n  });\n\n  it('should partial re-render with array name and exact option', async () => {\n    type FormInputs = {\n      child: string;\n      childSecond: string;\n      parent: string;\n    };\n\n    let childCount = 0;\n    let childSecondCount = 0;\n\n    const Child = ({\n      register,\n      control,\n    }: Pick<UseFormReturn<FormInputs>, 'register' | 'control'>) => {\n      return (\n        <>\n          <Watch\n            control={control}\n            names={['childSecond']}\n            render={() => {\n              childCount++;\n              return null;\n            }}\n          />\n          <input {...register('child')} />\n        </>\n      );\n    };\n\n    const ChildSecond = ({\n      register,\n      control,\n    }: Pick<UseFormReturn<FormInputs>, 'register' | 'control'>) => {\n      return (\n        <>\n          <Watch\n            control={control}\n            exact={true}\n            names={['childSecond']}\n            render={() => {\n              childSecondCount++;\n              return null;\n            }}\n          />\n          <input {...register('childSecond')} />\n        </>\n      );\n    };\n\n    let parentCount = 0;\n    const Parent = () => {\n      const {\n        register,\n        handleSubmit,\n        control,\n        formState: { errors },\n      } = useForm<FormInputs>();\n      parentCount++;\n      return (\n        <form onSubmit={handleSubmit(noop)}>\n          <>\n            <input {...register('parent')} />\n            <Child register={register} control={control} />\n            <ChildSecond register={register} control={control} />\n            <p>{String(errors.parent)}</p>\n            <button>submit</button>\n          </>\n        </form>\n      );\n    };\n\n    render(<Parent />);\n\n    const childInput = screen.getAllByRole('textbox')[1];\n    const childSecondInput = screen.getAllByRole('textbox')[2];\n\n    fireEvent.input(childInput, {\n      target: { value: 'test' },\n    });\n\n    expect(parentCount).toBe(2);\n    expect(childCount).toBe(3);\n    expect(childSecondCount).toBe(2);\n\n    parentCount = 0;\n    childCount = 0;\n    childSecondCount = 0;\n\n    fireEvent.submit(screen.getByRole('button', { name: /submit/i }));\n\n    await waitFor(() => expect(parentCount).toBe(1));\n    expect(childCount).toBe(2);\n    expect(childSecondCount).toBe(2);\n\n    parentCount = 0;\n    childCount = 0;\n    childSecondCount = 0;\n\n    fireEvent.input(childInput, { target: { value: 'test1' } });\n\n    expect(parentCount).toBe(0);\n    expect(childCount).toBe(1);\n    expect(childSecondCount).toBe(0);\n\n    parentCount = 0;\n    childCount = 0;\n    childSecondCount = 0;\n\n    fireEvent.input(childSecondInput, { target: { value: 'test2' } });\n\n    expect(parentCount).toBe(0);\n    expect(childCount).toBe(1);\n    expect(childSecondCount).toBe(1);\n  });\n\n  describe('when disabled prop is used', () => {\n    it('should be able to toggle subscription and start with disabled true', async () => {\n      type FormValues = {\n        test: string;\n      };\n\n      const ChildComponent = ({\n        control,\n      }: {\n        control: Control<FormValues>;\n      }) => {\n        const [disabled, setDisabled] = React.useState(true);\n\n        return (\n          <div>\n            <button\n              onClick={() => {\n                setDisabled(!disabled);\n              }}\n              type={'button'}\n            >\n              toggle\n            </button>\n            <Watch\n              control={control}\n              names=\"test\"\n              disabled={disabled}\n              render={(test) => {\n                return <p>{test}</p>;\n              }}\n            />\n          </div>\n        );\n      };\n\n      const App = () => {\n        const { register, control } = useForm<FormValues>({\n          defaultValues: {\n            test: 'test',\n          },\n        });\n\n        return (\n          <div>\n            <input {...register('test')} />\n            <ChildComponent control={control} />\n          </div>\n        );\n      };\n\n      render(<App />);\n\n      fireEvent.change(screen.getByRole('textbox'), {\n        target: {\n          value: 'what',\n        },\n      });\n\n      expect(screen.getByText('test')).toBeVisible();\n\n      fireEvent.click(screen.getByRole('button'));\n\n      fireEvent.change(screen.getByRole('textbox'), {\n        target: {\n          value: 'what12345',\n        },\n      });\n\n      expect(screen.getByText('what12345')).toBeVisible();\n\n      fireEvent.click(screen.getByRole('button'));\n\n      fireEvent.change(screen.getByRole('textbox'), {\n        target: {\n          value: '12345',\n        },\n      });\n\n      expect(screen.getByText('what12345')).toBeVisible();\n    });\n\n    it('should be able to toggle the subscription and start with disabled false', async () => {\n      type FormValues = {\n        test: string;\n      };\n\n      const ChildComponent = ({\n        control,\n      }: {\n        control: Control<FormValues>;\n      }) => {\n        const [disabled, setDisabled] = React.useState(false);\n\n        return (\n          <div>\n            <button\n              onClick={() => {\n                setDisabled(!disabled);\n              }}\n              type={'button'}\n            >\n              toggle\n            </button>\n            <Watch\n              control={control}\n              names=\"test\"\n              disabled={disabled}\n              render={(test) => <p>{test}</p>}\n            />\n          </div>\n        );\n      };\n\n      const App = () => {\n        const { register, control } = useForm<FormValues>({\n          defaultValues: {\n            test: 'test',\n          },\n        });\n\n        return (\n          <div>\n            <input {...register('test')} />\n            <ChildComponent control={control} />\n          </div>\n        );\n      };\n\n      render(<App />);\n\n      fireEvent.change(screen.getByRole('textbox'), {\n        target: {\n          value: 'what',\n        },\n      });\n\n      expect(screen.getByText('what')).toBeVisible();\n\n      fireEvent.click(screen.getByRole('button'));\n\n      fireEvent.change(screen.getByRole('textbox'), {\n        target: {\n          value: 'what12345',\n        },\n      });\n\n      expect(screen.getByText('what')).toBeVisible();\n    });\n  });\n\n  describe('compute ', () => {\n    it('should only update when value changed within compute', () => {\n      type FormValue = {\n        test: string;\n      };\n\n      let renderCount = 0;\n\n      const Form = () => {\n        const methods = useForm<FormValue>({\n          defaultValues: { test: '' },\n        });\n\n        return (\n          <div>\n            <input {...methods.register('test')} />\n            <Watch\n              control={methods.control}\n              compute={(data) => data.test?.length > 2}\n              render={(watchedValue) => {\n  