nknown[] = [];\n\n    function App() {\n      const { register, reset, control } = useForm({\n        defaultValues: { test: 'test' },\n        shouldUnregister: true,\n      });\n      const inputs = useWatch({ control });\n\n      output.push(inputs);\n\n      return (\n        <form>\n          <input {...register('test')} />\n          <button\n            type=\"button\"\n            onClick={() => reset(undefined, { keepDefaultValues: true })}\n          >\n            Reset\n          </button>\n        </form>\n      );\n    }\n\n    render(<App />);\n\n    fireEvent.click(screen.getByRole('button'));\n\n    fireEvent.change(screen.getByRole('textbox'), {\n      target: { value: 'test' },\n    });\n\n    fireEvent.click(screen.getByRole('button'));\n\n    expect(output).toEqual([\n      { test: 'test' },\n      { test: 'test' },\n      { test: 'test' },\n      { test: 'test' },\n      { test: 'test' },\n      { test: 'test' },\n    ]);\n  });\n\n  it('should subscribe to exact input change', () => {\n    const App = () => {\n      const { control, register } = useForm();\n      const value = useWatch({\n        name: 'test',\n        control,\n        exact: true,\n        defaultValue: 'test',\n      });\n\n      return (\n        <div>\n          <input {...register('test.0.data')} />\n          <p>{value}</p>\n        </div>\n      );\n    };\n\n    render(<App />);\n\n    fireEvent.change(screen.getByRole('textbox'), {\n      target: {\n        value: '1234',\n      },\n    });\n\n    expect(screen.getByText('test')).toBeVisible();\n  });\n\n  it('should return root object subscription', () => {\n    function App() {\n      const { register, control } = useForm({\n        defaultValues: { field: { firstName: 'value' } },\n      });\n      const field = useWatch({ control, name: 'field' });\n\n      return (\n        <div>\n          <form>\n            <input {...register('field.firstName')} placeholder=\"First Name\" />\n            <p>{field.firstName}