+{"version":3,"sources":["/workspace/repo/src/__tests__/formStateSubscribe.test.tsx"],"sourcesContent":["// __tests__/formState.component.test.tsx\nimport React from 'react';\nimport { fireEvent, render, screen, waitFor } from '@testing-library/react';\n\nimport { Controller } from '../controller';\nimport { FormStateSubscribe } from '../formStateSubscribe';\nimport type { Control } from '../types';\nimport { useFieldArray } from '../useFieldArray';\nimport { useForm } from '../useForm';\nimport { FormProvider } from '../useFormContext';\nimport deepEqual from '../utils/deepEqual';\nimport noop from '../utils/noop';\n\ndescribe('FormStateSubscribe', () => {\n  it('should render correct form state with isDirty, dirty, touched', () => {\n    let count = 0;\n\n    const Test = ({ control }: { control: Control<{ test: string }> }) => (\n      <FormStateSubscribe\n        control={control}\n        render={({ isDirty, dirtyFields, touchedFields }) => (\n          <>\n            <div>{isDirty ? 'isDirty' : ''}</div>\n            <div>{dirtyFields['test'] ? 'dirty field' : ''}</div>\n            <div>{touchedFields['test'] ? 'isTouched' : ''}</div>\n          </>\n        )}\n      />\n    );\n\n    const Component = () => {\n      const { register, control } = useForm<{ test: string }>();\n      count++;\n      return (\n        <div>\n          <input aria-label=\"test\" {...register('test')} />\n          <Test control={control} />\n        </div>\n      );\n    };\n\n    render(<Component />);\n\n    fireEvent.input(screen.getByLabelText('test'), {\n      target: { value: 'test' },\n    });\n    expect(screen.getByText('isDirty')).toBeVisible();\n    expect(screen.getByText('dirty field')).toBeVisible();\n    expect(count).toEqual(2);\n\n    fireEvent.blur(screen.getByLabelText('test'));\n    expect(screen.getByText('isTouched')).toBeVisible();\n    expect(count).toEqual(2);\n  });\n\n  it('should render correct isolated errors message', async () => {\n    let count = 0;\n\n    const Test = ({ control }: { control: Control }) => (\n      <FormStateSubscribe\n        control={control}\n        render={({ errors, isValid }) => (\n          <>\n            <div>{errors['test'] ? 'error' : 'valid'}</div>\n            <div>{isValid ? 'yes' : 'no'}</div>\n          </>\n        )}\n      />\n    );\n\n    const Component = () => {\n      const { register, control } = useForm({ mode: 'onChange' });\n      count++;\n      return (\n        <div>\n          <input aria-label=\"test\" {...register('test', { minLength: 5 })} />\n          <Test control={control} />\n        </div>\n      );\n    };\n\n    render(<Component />);\n\n    await waitFor(() => expect(screen.getByText('yes')).toBeVisible());\n\n    fireEvent.input(screen.getByLabelText('test'), {\n      target: { value: 'test' },\n    });\n    expect(await screen.findByText('error')).toBeVisible();\n    expect(screen.getByText('no')).toBeVisible();\n\n    fireEvent.input(screen.getByLabelText('test'), {\n      target: { value: 'testtest' },\n    });\n    expect(await screen.findByText('valid')).toBeVisible();\n    expect(screen.getByText('yes')).toBeVisible();\n\n    expect(count).toEqual(2);\n  });\n\n  it('should update isValidating correctly', async () => {\n    function Child() {\n      return (\n        <FormStateSubscribe\n          render={({ isDirty, isValid, isValidating }) => {\n            const enabled = !isValidating && isDirty && isValid;\n            return (\n              <button disabled={!enabled} type=\"submit\">\n                Submit\n              </button>\n            );\n          }}\n        />\n      );\n    }\n\n    function App() {\n      const form = useForm({ mode: 'onChange' });\n      const { register } = form;\n\n      return (\n        <FormProvider {...form}>\n          <form>\n            <input {...register('value', { required: true })} />\n            <Child />\n          </form>\n        </FormProvider>\n      );\n    }\n\n    render(<App />);\n\n    fireEvent.change(screen.getByRole('textbox'), { target: { value: '1' } });\n    await waitFor(() => expect(screen.getByRole('button')).not.toBeDisabled());\n\n    fireEvent.change(screen.getByRole('textbox'), { target: { value: '12' } });\n    await waitFor(() => expect(screen.getByRole('button')).not.toBeDisabled());\n  });\n\n  it('should update formState separately with multiple FormState instances', async () => {\n    let count = 0;\n    let testCount = 0;\n    let test1Count = 0;\n\n    const Test1 = ({ control }: { control: Control }) => (\n      <FormStateSubscribe\n        control={control}\n        render={({ isDirty, dirtyFields }) => {\n          testCount++;\n          return (\n            <>\n              <div>\n                {dirtyFields['test'] ? 'hasDirtyField' : 'notHasDirtyField'}\n              </div>\n              <div>{isDirty ? 'isDirty' : 'notDirty'}</div>\n            </>\n          );\n        }}\n      />\n    );\n\n    const Test = ({ control }: { control: Control }) => (\n      <FormStateSubscribe\n        control={control}\n        render={({ touchedFields }) => {\n          test1Count++;\n          return (\n            <div>{touchedFields['test'] ? 'isTouched' : 'notTouched'}</div>\n          );\n        }}\n      />\n    );\n\n    const Component = () => {\n      const { register, control } = useForm({ mode: 'onChange' });\n      count++;\n      return (\n        <div>\n          <input aria-label=\"test\" {...register('test', { minLength: 5 })} />\n          <Test control={control} />\n          <Test1 control={control} />\n        </div>\n      );\n    };\n\n    render(<Component />);\n\n    fireEvent.input(screen.getByLabelText('test'), {\n      target: { value: 'test' },\n    });\n\n    expect(await screen.findByText('hasDirtyField')).toBeVisible();\n    expect(screen.getByText('isDirty')).toBeVisible();\n\n    expect(count).toEqual(2);\n    expect(testCount).toEqual(3);\n    expect(test1Count).toEqual(2);\n\n   