+{"version":3,"sources":["/workspace/repo/src/__tests__/useForm/resetField.test.tsx"],"sourcesContent":["import React from 'react';\nimport { fireEvent, render, screen } from '@testing-library/react';\n\nimport { useForm } from '../../useForm';\n\ndescribe('resetField', () => {\n  it('should reset input value', () => {\n    const App = () => {\n      const { register, resetField } = useForm({\n        defaultValues: {\n          test: 'test',\n        },\n      });\n\n      return (\n        <form>\n          <input {...register('test')} />\n          <button\n            type={'button'}\n            onClick={() => {\n              resetField('test');\n            }}\n          >\n            reset\n          </button>\n        </form>\n      );\n    };\n\n    render(<App />);\n\n    fireEvent.change(screen.getByRole('textbox'), {\n      target: {\n        value: '1234',\n      },\n    });\n\n    expect((screen.getByRole('textbox') as HTMLInputElement).value).toEqual(\n      '1234',\n    );\n\n    fireEvent.click(screen.getByRole('button'));\n\n    expect((screen.getByRole('textbox') as HTMLInputElement).value).toEqual(\n      'test',\n    );\n  });\n\n  it('should reset input touched field state', async () => {\n    const App = () => {\n      const {\n        register,\n        resetField,\n        formState: { touchedFields },\n      } = useForm({\n        defaultValues: {\n          test: 'test',\n        },\n      });\n\n      return (\n        <form>\n          <input {...register('test')} />\n          <p>{touchedFields.test ? 'touched' : 'noTouched'}</p>\n          <button\n            type={'button'}\n            onClick={() => {\n              resetField('test');\n            }}\n          >\n            reset\n          </button>\n        </form>\n      );\n    };\n\n    render(<App />);\n\n    fireEvent.focus(screen.getByRole('textbox'));\n\n    fireEvent.blur(screen.getByRole('textbox'));\n\n    expect(await screen.findByText('touched')).toBeVisible();\n\n    fireEvent.click(screen.getByRole('button'));\n\n    expect(await screen.findByText('noTouched')).toBeVisible();\n  });\n\n  it('should reset input dirty field and dirty state', async () => {\n    const App = () => {\n      const {\n        register,\n        resetField,\n        formState: { dirtyFields, isDirty },\n      } = useForm({\n        defaultValues: {\n          test: 'test',\n        },\n      });\n\n      return (\n        <form>\n          <input {...register('test')} />\n          <p>{dirtyFields.test ? 'dirty' : 'notDirty'}</p>\n          <p>{isDirty ? 'formDirty' : 'formNotDirty'}</p>\n          <button\n            type={'button'}\n            onClick={() => {\n              resetField('test');\n            }}\n          >\n            reset\n          </button>\n        </form>\n      );\n    };\n\n    render(<App />);\n\n    fireEvent.change(screen.getByRole('textbox'), {\n      target: {\n        value: '1234',\n      },\n    });\n\n    expect(await screen.findByText('dirty')).toBeVisible();\n    expect(screen.getByText('formDirty')).toBeVisible();\n\n    fireEvent.click(screen.getByRole('button'));\n\n    expect(await screen.findByText('notDirty')).toBeVisible();\n    expect(screen.getByText('formNotDirty')).toBeVisible();\n  });\n\n  it('should reset input error field and isValid state', async () => {\n    const App = () => {\n      const {\n        register,\n        resetField,\n        formState: { errors, isValid },\n      } = useForm({\n        defaultValues: {\n          test: 'test',\n        },\n        mode: 'onChange',\n      });\n\n      return (\n        <form>\n          <input {...register('test', { maxLength: 4 })} />\n          <p>{errors.test ? 'error' : 'noError'}</p>\n          <p>{isValid ? 'valid' : 'NotValid'}</p>\n          <button\n            type={'button'}\n            onClick={() => {\n              resetField('test');\n            }}\n          >\n            reset\n          </button>\n        </form>\n      