+{"version":3,"sources":["/workspace/repo/src/__tests__/form.test.tsx"],"sourcesContent":["import 'whatwg-fetch';\n\nimport React from 'react';\nimport { fireEvent, render, screen, waitFor } from '@testing-library/react';\n\nimport { Form } from '../form';\nimport { useForm } from '../useForm';\nimport { FormProvider } from '../useFormContext';\n\ndescribe('Form', () => {\n  beforeEach(() => {\n    jest.restoreAllMocks();\n  });\n\n  it('should support render with both form tag and headless', () => {\n    const WithContext = () => (\n      <>\n        <Form />\n        <Form render={() => null} />\n      </>\n    );\n\n    const App = () => {\n      const methods = useForm();\n      return (\n        <div>\n          <Form control={methods.control}>\n            <input />\n          </Form>\n          <Form\n            control={methods.control}\n            render={() => {\n              return null;\n            }}\n          />\n\n          <FormProvider {...methods}>\n            <WithContext />\n          </FormProvider>\n        </div>\n      );\n    };\n\n    render(<App />);\n  });\n\n  it('should handle success request callback', async () => {\n    jest.spyOn(global, 'fetch').mockResolvedValueOnce(\n      new Response(JSON.stringify({ message: 'ok' }), {\n        status: 200,\n        headers: { 'Content-Type': 'application/json' },\n      }),\n    );\n\n    const onSubmit = jest.fn();\n    const onError = jest.fn();\n\n    const App = () => {\n      const [message, setMessage] = React.useState('');\n      const {\n        control,\n        formState: { isSubmitSuccessful },\n      } = useForm();\n\n      return (\n        <Form\n          encType={'application/json'}\n          action={'/success'}\n          onSubmit={({ data, formData, formDataJson }) => {\n            data;\n            formData;\n            formDataJson;\n            onSubmit();\n          }}\n          control={control}\n          onError={onError}\n          onSuccess={async ({ response }) => {\n            if (response) {\n              const data: { message: string } = await response.json();\n              setMessage(data.message);\n            }\n          }}\n        >\n          <button>Submit</button>\n          <p>{isSubmitSuccessful ? 'submitSuccessful' : 'submitFailed'}</p>\n          <p>{message}</p>\n        </Form>\n      );\n    };\n\n    render(<App />);\n\n    fireEvent.click(screen.getByRole('button'));\n\n    await waitFor(() => {\n      expect(onSubmit).toHaveBeenCalled();\n      expect(onError).not.toHaveBeenCalled();\n      screen.getByText('submitSuccessful');\n      screen.getByText('ok');\n    });\n  });\n\n  it('should handle error request callback', async () => {\n    jest\n      .spyOn(global, 'fetch')\n      .mockResolvedValueOnce(new Response(null, { status: 500 }));\n\n    const onSubmit = jest.fn();\n    const onSuccess = jest.fn();\n\n    const App = () => {\n      const {\n        control,\n        formState: { isSubmitSuccessful, errors },\n      } = useForm();\n\n      return (\n        <Form\n          encType={'application/json'}\n          action={'/error'}\n          onSubmit={onSubmit}\n          control={control}\n        >\n          <button>Submit</button>\n          <p>{isSubmitSuccessful ? 'submitSuccessful' : 'submitFailed'}</p>\n          {errors.root?.server && 'This is a server error'}\n          <p>{errors.root?.server?.type}</p>\n        </Form>\n      );\n    };\n\n    render(<App />);\n\n    fireEvent.click(screen.getByRole('button'));\n\n    await waitFor(() => {\n      expect(onSubmit).toHaveBeenCalled();\n      expect(onSuccess).not.toHaveBeenCalled();\n      screen.getByText('This is a server error');\n      screen.getByText('500');\n      screen.getByText('submitFailed');\n    });\n  });\n\n  it('should validate custom status code', async () => {\n    jest\n      .spyOn(global, 'fetch')\n      .mockResolvedValueOnce(new Response(null, { status: 201 }));\n\n    const App = () => {\n      const {\n        control,\n        formState: { isSubmitSuccessful },\n      } = useForm();\n\n      return (\n        <Form\n          encType={'application/json'}\n          action={'/status'}\n          control={control}\n          validateStatus={(status) => status === 200}\n        >\n          <button>Submit</button>\n          <p>{isSubmitSuccessful ? 'submitSuccessful' : 'submitFailed'}</p>\n        </Form>\n      );\n    };\n\n    render(<App />);\n\n    fireEvent.click(screen.getByRole('button'));\n\n    await waitFor(() => {\n      screen.getByText('submitFailed');\n    });\n  });\n\n  it('should support other request type', async () => {\n    jest\n      .spyOn(global, 'fetch')\n      .mockResolvedValueOnce(new Response(null, { status: 200 }));\n\n    const App = () => {\n      const {\n        control,\n        formState: { isSubmitSuccessful },\n      } = useForm();\n\n      return (\n        <Form encType={'application/json'} action={'/get'} control={control}>\n          <button>Submit</button>\n          <p>{isSubmitSuccessful ? 'submitSuccessful' : 'submitFailed'}</p>\n        </Form>\n      );\n    };\n\n    render(<App />);\n\n    fireEvent.click(screen.getByRole('button'));\n\n    await waitFor(() => {\n      screen.getByText('submitSuccessful');\n    });\n  });\n\n  it('should support render props for react native', async () => {\n    jest\n      .spyOn(global, 'fetch')\n      .mockResolvedValueOnce(new Response(null, { status: 200 }));\n\n    const App = () => {\n      const {\n        control,\n        formState: { isSubmitSuccessful },\n      } = useForm();\n\n      return (\n        <Form\n          control={control}\n          render={({ submit }) => {\n            return (\n              <>\n                <button onClick={() => submit()}>Submit</button>\n                <p>\n                  {isSubmitSuccessful ? 'submitSuccessful' : 'submitFailed'}\n                </p>\n              </>\n            );\n          }}\n        />\n      );\n    };\n\n    render(<App />);\n\n    fireEvent.click(screen.getByRole('button'));\n\n    await waitFor(() => {\n      screen.getByText('submitSuccessful');\n    });\n  });\n\n  it('should support fetcher prop with external request', async () => {\n    const fetcher = jest.fn().mockResolvedValue({});\n    jest\n      .spyOn(global, 'fetch')\n      .mockResolvedValueOnce(new Response(null, { status: 200 }));\n\n    const App = () => {\n      const {\n        control,\n        formState: { isSubmitSuccessful },\n      } = useForm();\n\n      return (\n        <Form\n          control={control}\n          onSubmit={async () => {\n            await fetcher();\n          }}\n        >\n          <button>Submit</button>\n          <p>{isSubmitSuccessful ? 'submitSuccessful' : 'submitFailed'}</p>\n        </Form>\n      );\n    };\n\n    render(<App />);\n\n    fireEvent.click(screen.getByRole('button'));\n\n    await waitFor(() => {\n      screen.getByText('submitSuccessful');\n\n      expect(fetcher).toHaveBeenCalled();\n    });\n  });\n\n  it('should include application/json header with encType supplied', async () => {\n    jest\n      .spyOn(global, 'fetch')\n      .mockResolvedValueOnce(new Response(null, { status: 200 }));\n\n    const onSuccess = jest.fn();\n\n    const App = () => {\n      const {\n        control,\n        formState: { isSubmitSuccessful },\n      } = useForm();\n\n      return (\n        <Form\n          encType={'application/json'}\n          action={'/json'}\n          control={control}\n          onSuccess={onSuccess}\n        >\n          <button>Submit</button>\n          <p>{isSubmitSuccessful ? 'submitSuccessful' : 'submitFailed'}</p>\n        </Form>\n      );\n    };\n\n    render(<App />);\n\n    fireEvent.click(screen.getByRole('button'));\n\n    await waitFor(() => {\n      expect(onSuccess).toHaveBeenCalled();\n    });\n  });\n\n  it('should support explicit \"multipart/form-data\" encType', async () => {\n    jest\n      .spyOn(global, 'fetch')\n      .mockResolvedValueOnce(new Response(null, { status: 200 }));\n\n    const onSuccess = jest.fn();\n\n    const App = () => {\n      const {\n        control,\n        formState: { isSubmitSuccessful },\n      } = useForm();\n\n      return (\n        <Form\n          encType={'multipart/form-data'}\n          action={'/formData'}\n          control={control}\n          onSuccess={onSuccess}\n        >\n          <button>Submit</button>\n          <p>{isSubmitSuccessful ? 'submitSuccessful' : 'submitFailed'}</p>\n        </Form>\n      );\n    };\n\n    render(<App />);\n\n    fireEvent.click(screen.getByRole('button'));\n\n    await waitFor(() => {\n      expect(onSuccess).toHaveBeenCalled();\n    });\n  });\n});\n"],"names":["describe","beforeEach","jest","restoreAllMocks","it","WithContext","Form","render","App","methods","useForm","div","control","input","FormProvider","spyOn","global","mockResolvedValueOnce","Response","JSON","stringify","message","status","headers","onSubmit","fn","onError","setMessage","React","useState","formState","isSubmitSuccessful","encType","action","data","formData","formDataJson","onSuccess","response","json","button","p","fireEvent","click","screen","getByRole","waitFor","expect","toHaveBeenCalled","not","getByText","errors","root","server","type","validateStatus","submit","onClick","fetcher","mockResolvedValue"],"mappings":";;;;QAAO;8DAEW;wBACiC;sBAE9B;yBACG;gCACK;;;;;;AAE7BA,SAAS,QAAQ;IACfC,WAAW;QACTC,KAAKC,eAAe;IACtB;IAEAC,GAAG,yDAAyD;QAC1D,MAAMC,cAAc,kBAClB,0EACE,6BAACC,UAAI,uBACL,6BAACA,UAAI;gBAACC,QAAQ,IAAM;;QAIxB,MAAMC,MAAM;YACV,MAAMC,UAAUC,IAAAA,gBAAO;YACvB,qBACE,6BAACC,2BACC,6BAACL,UAAI;gBAACM,SAASH,QAAQG,OAAO;6BAC5B,6BAACC,+BAEH,6BAACP,UAAI;gBACHM,SAASH,QAAQG,OAAO;gBACxBL,QAAQ;oBACN,OAAO;gBACT;8BAGF,6BAACO,4BAAY,EAAKL,uBAChB,6BAACJ;QAIT;QAEAE,IAAAA,cAAM,gBAAC,6BAACC;IACV;IAEAJ,GAAG,0CAA0C;QAC3CF,KAAKa,KAAK,CAACC,QAAQ,SAASC,qBAAqB,CAC/C,IAAIC,SAASC,KAAKC,SAAS,CAAC;YAAEC,SAAS;QAAK,IAAI;YAC9CC,QAAQ;YACRC