+{"version":3,"sources":["/workspace/repo/src/__tests__/useForm/setError.test.tsx"],"sourcesContent":["import React from 'react';\nimport {\n  act,\n  fireEvent,\n  render,\n  renderHook,\n  screen,\n  waitFor,\n} from '@testing-library/react';\n\nimport type {\n  DeepMap,\n  ErrorOption,\n  FieldError,\n  GlobalError,\n} from '../../types';\nimport { useForm } from '../../useForm';\nimport { FormProvider, useFormContext } from '../../useFormContext';\n\ndescribe('setError', () => {\n  const tests: [string, ErrorOption, DeepMap<any, FieldError>][] = [\n    [\n      'should only set an error when it is not existed',\n      { type: 'test' },\n      {\n        input: {\n          type: 'test',\n          message: undefined,\n          ref: undefined,\n        },\n      },\n    ],\n    [\n      'should set error message',\n      { type: 'test', message: 'test' },\n      {\n        input: {\n          type: 'test',\n          message: 'test',\n          ref: undefined,\n          types: undefined,\n        },\n      },\n    ],\n    [\n      'should set multiple error type',\n      {\n        types: { test1: 'test1', test2: 'test2' },\n      },\n      {\n        input: {\n          types: {\n            test1: 'test1',\n            test2: 'test2',\n          },\n          ref: undefined,\n        },\n      },\n    ],\n  ];\n\n  it.each(tests)('%s', (_, input, output) => {\n    const { result } = renderHook(() => useForm<{ input: string }>());\n\n    result.current.formState.errors;\n\n    act(() => {\n      result.current.setError('input', input);\n    });\n    expect(result.current.formState.errors).toEqual(output);\n    expect(result.current.formState.isValid).toBeFalsy();\n  });\n\n  it('should update isValid with setError', async () => {\n    const App = () => {\n      const {\n        formState: { isValid },\n        setError,\n      } = useForm({\n        mode: 'onChange',\n      });\n\n      return (\n        <div>\n          <button\n            type={'button'}\n            onClick={() => {\n              setError('test', { type: 'test' });\n            }}\n          >\n            setError\n          </button>\n          {isValid ? 'yes' : 'no'}\n        </div>\n      );\n    };\n\n    render(<App />);\n\n    expect(await screen.findByText('yes')).toBeVisible();\n\n    fireEvent.click(screen.getByRole('button'));\n\n    expect(await screen.findByText('no')).toBeVisible();\n  });\n\n  it('should allow to set global error', async () => {\n    const onSubmit = jest.fn();\n\n    type Errors = {\n      root: {\n        customError: GlobalError;\n        serverError: GlobalError;\n      };\n    };\n\n    type FormValues = {\n      test: string;\n    };\n\n    const App = () => {\n      const {\n        formState: { errors },\n        handleSubmit,\n        setError,\n      } = useForm<FormValues & Errors>({\n        mode: 'onChange',\n      });\n\n      return (\n        <form\n          onSubmit={handleSubmit(() => {\n            onSubmit();\n            setError('root.serverError', {\n              type: '404',\n              message: 'not found',\n            });\n          })}\n        >\n          <button\n            type={'button'}\n            onClick={() => {\n              setError('root.customError', {\n                type: 'custom',\n                message: 'custom error',\n              });\n            }}\n          >\n            setError\n          </button>\n\n          <p>{errors?.root?.customError?.message}</p>\n          <p>{errors?.root?.serverError?.message}</p>\n\n          <button>submit</button>\n        </form>\n      );\n    };\n\n    render(<App />);\n\n    fireEvent.click(screen.getByRole('button', { name: 'setError' }));\n\n    await waitFor(() => {\n      screen.findByText('custom error');\n    });\n\n    fireEvent.click(screen.getByRole('button', { name: 'submit' }));\n\n    await waitFor(() => {\n      expect(onSubmit).toHaveBeenCalled();\n      expect(screen.queryByText('custom error')).not.toBeInTheDocument();\n    });\n\n    await waitFor(() => {\n      screen.findByText('not found');\n    });\n  });\n\n  it('should allow sequential calls to set with child after ancestor', async () => {\n    const { result } = renderHook(() =>\n      useForm<{ input: { first: string; last: string } }>(),\n    );\n    result.current.formState.errors;\n\n    act(() => {\n      result.current.setError('input', {\n        type: 'test',\n        message: 'Some error that depends on both fields',\n      });\n    });\n\n    expect(result.current.formState.errors).toEqual({\n      input: {\n        type: 'test',\n        message: 'Some error that depends on both fields',\n        ref: undefined,\n      },\n    });\n\n    act(() => {\n      result.current.setError('input.first', {\n        type: 'test',\n        message: 'Name must be capitalized',\n      });\n    });\n\n    expect(result.current.formState.errors).toEqual({\n      input: {\n        type: 'test',\n        message: 'Some error that depends on both fields',\n        ref: undefined,\n        first: {\n          type: 'test',\n          message: 'Name must be capitalized',\n          ref: undefined,\n        },\n      },\n    });\n  });\n\n  it('should allow sequential calls to set with ancestor after child', async () => {\n    const { result } = renderHook(() =>\n      useForm<{ input: { first: string; last: string } }>(),\n    );\n\n    result.current.formState.errors;\n\n    act(() => {\n      result.current.setError('input.first', {\n        type: 'test',\n        message: 'Name must be capitalized',\n      });\n    });\n\n    expect(result.current.formState.errors).toEqual({\n      input: {\n        first: {\n          type: 'test',\n          message: 'Name must be capitalized',\n          ref: undefined,\n        },\n      },\n    });\n\n    act(() => {\n      result.current.setError('input', {\n        type: 'test',\n        message: 'Some error that depends on both fields',\n      });\n    });\n\n    expect(result.current.formState.errors).toEqual({\n      input: {\n        type: 'test',\n        message: 'Some error that depends on both fields',\n        ref: undefined,\n        first: {\n          type: 'test',\n          message: 'Name must be capitalized',\n          ref: undefined,\n        },\n      },\n    });\n  });\n});\n\nit('should update error state in FormProvider when setError is called in useEffect', async () => {\n  type FormValues = {\n    firstname: string;\n    lastname: string;\n  };\n\n  const MyForm = () => {\n    const {\n      register,\n      setError,\n      formState: { errors },\n    } = useFormContext<FormValues>();\n\n    React.useEffect(() => {\n      setError('firstname', { type: 'manual', message: 'This is an error' });\n    }, [setError]);\n\n    return (\n      <form>\n        <div>\n          <input {...register('firstname')} placeholder=\"firstname\" />\n          {errors.firstname && <p>{errors.firstname.message}</p>}\n        </div>\n        <div>\n          <input {...register('lastname')} placeholder=\"lastname\" />\n        </div>\n      </form>\n    );\n  };\n\n  const App = () => {\n    const methods = useForm<FormValues>();\n    return (\n      <FormProvider {...methods}>\n        <MyForm />\n      </FormProvider>\n    );\n  };\n\n  render(<App />);\n\n  await waitFor(() => {\n    expect(screen.getByText('This is an error')).toBeInTheDocument();\n  });\n});\n"],"names":["describe","tests","type","input","message","undefined","ref","types","test1","test2","it","each","_","output","result","renderHook","useForm","current","formState","errors","act","setError","expect","toEqual","isValid","toBeFalsy","App","mode","div","button","onClick","render","screen","findByText","toBeVisible","fireEvent","click","getByRole","onSubmit","jest","fn","handleSubmit","form","p","root","customError","serverError","name","waitFor","toHaveBeenCalled","queryByText","not","toBeInTheDocument","first","MyForm","register","useFormContext","React","useE