+{"version":3,"sources":["/workspace/repo/src/__tests__/useController.test.tsx"],"sourcesContent":["import React, { useEffect, useMemo, useState } from 'react';\nimport {\n  fireEvent,\n  render,\n  renderHook,\n  screen,\n  waitFor,\n} from '@testing-library/react';\n\nimport { Controller } from '../controller';\nimport type { Control, FieldPath, FieldValues, UseFormReturn } from '../types';\nimport { useController } from '../useController';\nimport { useForm } from '../useForm';\nimport { FormProvider, useFormContext } from '../useFormContext';\nimport isBoolean from '../utils/isBoolean';\nimport noop from '../utils/noop';\n\ndescribe('useController', () => {\n  it('should render input correctly', () => {\n    const Component = () => {\n      const { control } = useForm<{\n        test: string;\n        test1: { test: string }[];\n      }>();\n\n      useController({\n        name: 'test',\n        control,\n        defaultValue: '',\n      });\n\n      return null;\n    };\n\n    render(<Component />);\n  });\n\n  it('component using the hook can be memoized', async () => {\n    function App() {\n      const form = useForm({\n        values: { login: 'john' },\n      });\n\n      return useMemo(() => <LoginField form={form} />, [form]);\n    }\n\n    function LoginField({ form }: { form: UseFormReturn<{ login: string }> }) {\n      const ctrl = useController({\n        name: 'login',\n        control: form.control,\n      });\n\n      return <input {...ctrl.field} />;\n    }\n\n    render(<App />);\n\n    const input = screen.getAllByRole<HTMLInputElement>('textbox')[0];\n    expect(input.value).toBe('john');\n\n    fireEvent.input(input, { target: { value: 'abc' } });\n    expect(input.value).toBe('abc');\n  });\n\n  it(\"setting values doesn't cause fields to be unregistered\", async () => {\n    function App() {\n      const [values, setValues] = useState<{ login: string } | undefined>();\n\n      const form = useForm({\n        values,\n      });\n\n      useEffect(() => {\n        setTimeout(() => {\n          setValues({ login: 'john' });\n        }, 100);\n      }, []);\n\n      return useMemo(\n        () => values?.login && <LoginField form={form} />,\n        [values, form],\n      );\n    }\n\n    function LoginField({ form }: { form: UseFormReturn<{ login: string }> }) {\n      const ctrl = useController({\n        name: 'login',\n        control: form.control,\n        defaultValue: 'john',\n      });\n\n      return <input value={ctrl.field.value} onChange={ctrl.field.onChange} />;\n    }\n\n    render(<App />);\n\n    const input = await screen.findByRole<HTMLInputElement>('textbox');\n    expect(input.value).toBe('john');\n\n    fireEvent.input(input, { target: { value: 'jane' } });\n    expect(input.value).toBe('jane');\n  });\n\n  it('should only subscribe to formState at each useController level', async () => {\n    const renderCounter = [0, 0];\n    type FormValues = {\n      test: string;\n      test1: string;\n    };\n\n    const Test = ({ control }: { control: Control<FormValues> }) => {\n      const { field } = useController({\n        name: 'test',\n        control,\n      });\n\n      renderCounter[0]++;\n\n      return <input {...field} />;\n    };\n\n    const Test1 = ({ control }: { control: Control<FormValues> }) => {\n      const {\n        field,\n        fieldState: { isDirty, isTouched },\n      } = useController({\n        name: 'test1',\n        control,\n      });\n\n      renderCounter[1]++;\n\n      return (\n        <div>\n          <input {...field} />\n          {isDirty && <p>isDirty</p>}\n          {isTouched && <p>isTouched</p>}\n        </div>\n      );\n    };\n\n    const Component = () => {\n      const { control } = useForm<FormValues>({\n        defaultValues: {\n          test: '',\n          test1: '',\n        },\n      });\n\n      return (\n        <div>\n          <Test control={control} />\n          <Test1 control={control} />\n        </div>\n      );\n    };\n\n    render(<Component />);\n\n    expect(renderCounter).toEqual([2, 2]);\n\n    fireEvent.change(screen.getAllByRole('textbox')[1], {\n      target: {\n        value: '1232',\n      },\n    });\n\n    expect(screen.getByText('isDirty')).toBeVisible();\n\n    fireEvent.blur(screen.getAllByRole('textbox')[1]);\n\n    expect(screen.getByText('isTouched')).toBeVisible();\n\n    expect(renderCounter).toEqual([2, 4]);\n\n    fireEvent.change(screen.getAllByRole('textbox')[0], {\n      target: {\n        value: '1232',\n      },\n    });\n\n    fireEvent.blur(screen.getAllByRole('textbox')[0]);\n\n    expect(renderCounter).toEqual([4, 4]);\n  });\n\n  describe('checkbox', () => {\n    it('should work for checkbox by spread the field object', async () => {\n      const watchResult: unknown[] = [];\n      const Component = () => {\n        const { control, watch } = useForm<{\n          test: string;\n        }>();\n\n        watchResult.push(watch());\n\n        const { field } = useController({\n          name: 'test',\n          control,\n          defaultValue: '',\n        });\n\n        return <input type=\"checkbox\" {...field} />;\n      };\n\n      render(<Component />);\n\n      expect(watchResult).toEqual([{}, { test: '' }]);\n\n      fireEvent.click(screen.getByRole('checkbox'));\n\n      expect(watchResult).toEqual([{}, { test: '' }, { test: true }]);\n\n      fireEvent.click(screen.getByRole('checkbox'));\n\n      expect(watchResult).toEqual([\n        {},\n        { test: '' },\n        { test: true },\n        { test: false },\n      ]);\n    });\n\n    it('should work for checkbox by assign checked', async () => {\n      const watchResult: unknown[] = [];\n      const Component = () => {\n        const { control, watch } = useForm<{\n          test: string;\n        }>();\n\n        watchResult.push(watch());\n\n        const { field } = useController({\n          name: 'test',\n          control,\n          defaultValue: '',\n        });\n\n        return (\n          <input\n            type=\"checkbox\"\n            checked={!!field.value}\n            onChange={(e) => field.onChange(e.target.checked)}\n          />\n        );\n      };\n\n      render(<Component />);\n\n      expect(watchResult).toEqual([{}, { test: '' }]);\n\n      fireEvent.click(screen.getByRole('checkbox'));\n\n      expect(watchResult).toEqual([{}, { test: '' }, { test: true }]);\n\n      fireEvent.click(screen.getByRole('checkbox'));\n\n      expect(watchResult).toEqual([\n        {},\n        { test: '' },\n        { test: true },\n        { test: false },\n      ]);\n    });\n\n    it('should work for checkbox by assign value manually', async () => {\n      const watchResult: unknown[] = [];\n      const Component = () => {\n        const { control, watch } = useForm<{\n          test: string;\n        }>();\n\n        watchResult.push(watch());\n\n        const { field } = useController({\n          name: 'test',\n          control,\n          defaultValue: '',\n        });\n\n        return (\n          <input\n            value=\"on\"\n            type=\"checkbox\"\n            checked={!!field.value}\n            onChange={(e) =>\n              field.onChange(e.target.checked ? e.target.value : false)\n            }\n          />\n        );\n      };\n\n      render(<Component />);\n\n      expect(watchResult).toEqual([{}, { test: '' }]);\n\n      fireEvent.click(screen.getByRole('checkbox'));\n\n      expect(watchResult).toEqual([{}, { test: '' }, { test: 'on' }]);\n\n      fireEvent.click(screen.getByRole('checkbox'));\n\n      expect(watchResult).toEqual([\n        {},\n        { test: '' },\n        { test: 'on' },\n        { test: false },\n      ]);\n    });\n  });\n\n  it('should subscribe to formState update with trigger re-render at root', () => {\n    type FormValues = {\n      test: string;\n    };\n    let counter = 0;\n\n    const Test = ({ control }: { control: Control<FormValues> }) => {\n      const { field, formState } = useController({\n        control,\n        name: 'test',\n      });\n\n      return (\n        <>\n          <input {...field} />\n          <p>{formState.dirtyFields.test && 'dirty'}</p>\n          <p>{formState.touchedFields.test && 'touched'}</p>\n        </>\n      );\n    };\n\n    const Component = () => {\n      const { control } = useForm<FormValues>({\n        defaultValues: {\n          test: '',\n        },\n      });\n      counter++;\n\n      return <Test control={control} />;\n    };\n\n    render(<Component />);\n\n    fireEvent.change(screen.getByRole('textbox'), {\n      target: {\n        value: 'test',\n      },\n    });\n\n    fireEvent.blur(screen.getByRole('textbox'));\n\n    expect(counter).toEqual(2);\n\n    expect(screen.getByText('dirty')).toBeVisible();\n    expect(screen.getByText('touched')).toBeVisible();\n  });\n\n  it('should not overwrite defaultValues with defaultValue', () => {\n    const App = () => {\n      const { control } = useForm({\n        defaultValues: {\n          test: 'bill',\n        },\n      });\n\n      return (\n        <Controller\n          render={({ field }) => {\n            return <input {...field} />;\n          }}\n          control={control}\n          name={'test'}\n          defaultValue={'luo'}\n        />\n      );\n    };\n\n    render(<App />);\n\n    expect((screen.getByRole('textbox') as HTMLInputElement).value).toBe(\n      'bill',\n    );\n  });\n\n  it('should be able to update input value without ref', () => {\n    const App = () => {\n      const { control, setValue } = useForm();\n      const { field } = useController({\n        control,\n        name: 'test',\n        defaultValue: '',\n      });\n\n      return (\n        <div>\n          <input value={field.value} onChange={field.onChange} />\n          <button\n            onClick={() => {\n              setValue('test', 'data');\n            }}\n          >\n            setValue\n          </button>\n        </div>\n      );\n    };\n\n    render(<App />);\n\n    fireEvent.click(screen.getByRole('button'));\n\n    expect((screen.getByRole('textbox') as HTMLInputElement).value).toEqual(\n      'data',\n    );\n  });\n\n  it('should not change reference for onChange and onBlur on input value change', () => {\n    let counter = 0;\n\n    const App = () => {\n      const { control } = useForm();\n      const { field } = useController({\n        control,\n        name: 'test',\n        defaultValue: '',\n      });\n\n      useEffect(() => {\n        counter++;\n        field.onBlur;\n        field.onChange;\n        field.ref;\n      }, [field.onChange, field.onBlur, field.ref]);\n\n      return (\n        <div>\n          <input value={field.value} onChange={field.onChange} />\n          <button\n            onClick={() => {\n              field.onChange('data');\n            }}\n          >\n            setValue\n          </button>\n        </div>\n      );\n    };\n\n    render(<App />);\n\n    fireEvent.change(screen.getByRole('textbox'), {\n      target: {\n        value: 'b',\n      },\n    });\n    fireEvent.change(screen.getByRole('textbox'), {\n      target: {\n        value: 'bi',\n      },\n    });\n    fireEvent.change(screen.getByRole('textbox'), {\n      target: {\n        value: 'bil',\n      },\n    });\n    fireEvent.change(screen.getByRole('textbox'), {\n      target: {\n        value: 'bill',\n      },\n    });\n\n    expect(counter).toEqual(1);\n  });\n\n  it('should be able to setValue after reset', async () => {\n    let renderCount = 0;\n\n    type FormValues = {\n      name: string;\n    };\n\n    const Input = ({ control }: { control: Control<FormValues> }) => {\n      renderCount++;\n      const { field } = useController({\n        name: 'name',\n        control,\n        defaultValue: '',\n      });\n\n      return <input {...field} />;\n    };\n\n    function App() {\n      const { reset, control, setValue } = useForm<FormValues>();\n\n      React.useEffect(() => {\n        reset({ name: 'initial' });\n      }, [reset]);\n\n      return (\n        <div>\n          <Input control={control} />\n          <button type=\"button\" onClick={() => setValue('name', 'test', {})}>\n            setValue\n          </button>\n        </div>\n      );\n    }\n\n    render(<App />);\n\n    fireEvent.click(screen.getByRole('button'));\n\n    expect((screen.getByRole('textbox') as HTMLInputElement).value).toEqual(\n      'test',\n    );\n    expect(renderCount).toEqual(3);\n  });\n\n  it('should invoke native validation with Controller', async () => {\n    const setCustomValidity = jest.fn();\n    const reportValidity = jest.fn();\n    const focus = jest.fn();\n    const message = 'This is required';\n\n    type FormValues = {\n      test: string;\n    };\n\n    function Input({ control }: { control: Control<FormValues> }) {\n      const { field } = useController({\n        control,\n        rules: { required: message },\n        name: 'test',\n      });\n\n      return (\n        <div>\n          <input\n            {...field}\n            ref={() => {\n              field.ref({\n                focus,\n                setCustomValidity,\n                reportValidity,\n              });\n            }}\n          />\n        </div>\n      );\n    }\n\n    function App() {\n      const { handleSubmit, control } = useForm<FormValues>({\n        defaultValues: {\n          test: '',\n        },\n        mode: 'onChange',\n        shouldUseNativeValidation: true,\n      });\n\n      return (\n        <form onSubmit={handleSubmit(noop)}>\n          <Input control={control} />\n          <input type=\"submit\" />\n        </form>\n      );\n    }\n\n    render(<App />);\n\n    fireEvent.click(screen.getByRole('button'));\n\n    expect(setCustomValidity).toHaveBeenCalledWith(message);\n    expect(reportValidity).toHaveBeenCalled();\n\n    fireEvent.change(screen.getByRole('textbox'), {\n      target: {\n        value: 'bill',\n      },\n    });\n\n    fireEvent.click(screen.getByRole('button'));\n\n    await waitFor(() => expect(setCustomValidity).toHaveBeenCalledTimes(3));\n    expect(reportValidity).toHaveBeenCalledTimes(3);\n  });\n\n  it('should update with inline defaultValue', async () => {\n    const onSubmit = jest.fn();\n    const App = () => {\n      const { control, handleSubmit } = useForm();\n      useController({ control, defaultValue: 'test', name: 'test' });\n\n      return (\n        <form\n          onSubmit={handleSubmit((data) => {\n            onSubmit(data);\n          })}\n        >\n          <button>submit</button>\n        </form>\n      );\n    };\n\n    render(<App />);\n\n    fireEvent.click(screen.getByRole('button'));\n\n    await waitFor(() =>\n      expect(onSubmit).toHaveBeenCalledWith({\n        test: 'test',\n      }),\n    );\n  });\n\n  it('should return defaultValues when component is not yet mounted', async () => {\n    const defaultValues = {\n      test: {\n        deep: [\n          {\n            test: '0',\n            test1: '1',\n          },\n        ],\n      },\n    };\n\n    const App = () => {\n      const { control, getValues } = useForm<{\n        test: {\n          deep: { test: string; test1: string }[];\n        };\n      }>({\n        defaultValues,\n      });\n\n      const { field } = useController({\n        control,\n        name: 'test.deep.0.test',\n      });\n\n      return (\n        <div>\n          <input {...field} />\n          <p>{JSON.stringify(getValues())}</p>\n        </div>\n      );\n    };\n\n    render(<App />);\n\n    expect(true).toEqual(true);\n\n    expect(\n      await screen.findByText('{\"test\":{\"deep\":[{\"test\":\"0\",\"test1\":\"1\"}]}}'),\n    ).toBeVisible();\n  });\n\n  it('should trigger extra re-render and update latest value when setValue called during mount', async () => {\n    const Child = () => {\n      const { setValue } = useFormContext();\n      const {\n        field: { value },\n      } = useController({\n        name: 'content',\n      });\n\n      React.useEffect(() => {\n        setValue('content', 'expected value');\n      }, [setValue]);\n\n      return <p>{value}</p>;\n    };\n\n    function App() {\n      const methods = useForm({\n        defaultValues: {\n          content: 'default',\n        },\n      });\n\n      return (\n        <FormProvider {...methods}>\n          <form>\n            <Child />\n            <input type=\"submit\" />\n          </form>\n        </FormProvider>\n      );\n    }\n\n    render(<App />);\n\n    expect(await screen.findByText('expected value')).toBeVisible();\n  });\n\n  it('should remount with input with current formValue', () => {\n    let data: unknown;\n\n    function Input<T extends FieldValues>({\n      control,\n      name,\n    }: {\n      control: Control<T>;\n      name: FieldPath<T>;\n    }) {\n      const {\n        field: { value },\n      } = useController({\n        control,\n        name,\n        shouldUnregister: true,\n      });\n\n      data = value;\n\n      return null;\n    }\n\n    const App = () => {\n      const { control } = useForm<{\n        test: string;\n      }>({\n        defaultValues: {\n          test: 'test',\n        },\n      });\n      const [toggle, setToggle] = React.useState(true);\n\n      return (\n        <div>\n          {toggle && <Input control={control} name={'test'} />}\n          <button onClick={() => setToggle(!toggle)}>toggle</button>\n        </div>\n      );\n    };\n\n    render(<App />);\n\n    expect(data).toEqual('test');\n\n    fireEvent.click(screen.getByRole('button'));\n\n    fireEvent.click(screen.getByRole('button'));\n\n    expect(data).toBeUndefined();\n  });\n\n  it('should always get the latest value for onBlur event', async () => {\n    const watchResults: unknown[] = [];\n\n    const App = () => {\n      const { control, watch } = useForm();\n      const { field } = useController({\n        control,\n        name: 'test',\n        defaultValue: '',\n      });\n\n      watchResults.push(watch());\n\n      return (\n        <button\n          onClick={() => {\n            field.onChange('updated value');\n            field.onBlur();\n          }}\n        >\n          test\n        </button>\n      );\n    };\n\n    render(<App />);\n\n    fireEvent.click(screen.getByRole('button'), {\n      target: {\n        value: 'test',\n      },\n    });\n\n    expect(watchResults).toEqual([\n      {},\n      {\n        test: '',\n      },\n      {\n        test: 'updated value',\n      },\n    ]);\n  });\n\n  it('should focus and select the input text', async () => {\n    const select = jest.fn();\n    const focus = jest.fn();\n\n    const App = () => {\n      const { control, setFocus } = useForm({\n        defaultValues: {\n          test: 'data',\n        },\n      });\n      const { field } = useController({\n        control,\n        name: 'test',\n      });\n\n      field.ref({\n        select,\n        focus,\n      });\n\n      React.useEffect(() => {\n        setFocus('test', { shouldSelect: true });\n      }, [setFocus]);\n\n      return null;\n    };\n\n    render(<App />);\n\n    await waitFor(() => {\n      expect(select).toHaveBeenCalled();\n      expect(focus).toHaveBeenCalled();\n    });\n  });\n\n  it('should update isValid correctly with strict mode', async () => {\n    const App = () => {\n      const form = useForm({\n        mode: 'onChange',\n        defaultValues: {\n          name: '',\n        },\n      });\n      const { isValid } = form.formState;\n\n      return (\n        <FormProvider {...form}>\n          <Controller\n            render={({ field }) => (\n              <input value={field.value} onChange={field.onChange} />\n            )}\n            name=\"name\"\n            rules={{\n              required: true,\n            }}\n          />\n          <p>{isValid ? 'valid' : 'not'}</p>\n        </FormProvider>\n      );\n    };\n\n    render(<App />, { reactStrictMode: true });\n\n    await waitFor(() => {\n      screen.getByText('not');\n    });\n  });\n\n  it('should restore defaultValue from Controller with react strict mode double useEffect', async () => {\n    const onSubmit = jest.fn();\n\n    function App() {\n      const { handleSubmit, control } = useForm({\n        shouldUnregister: true,\n      });\n\n      return (\n        <form\n          onSubmit={handleSubmit((data) => {\n            onSubmit(data);\n          })}\n        >\n          <Controller\n            control={control}\n            name=\"firstName\"\n            defaultValue={'luo'}\n            render={({ field }) => <input {...field} />}\n          />\n\n          <button>submit</button>\n        </form>\n      );\n    }\n\n    render(<App />, { reactStrictMode: true });\n\n    fireEvent.click(screen.getByRole('button'));\n\n    await waitFor(() => {\n      expect(onSubmit).toHaveBeenCalledWith({\n        firstName: 'luo',\n      });\n    });\n  });\n\n  it('should restore defaultValues with react strict mode double useEffect', () => {\n    function Form() {\n      return (\n        <Controller\n          name=\"lastName\"\n          shouldUnregister={true}\n          render={({ field }) => <input {...field} />}\n        />\n      );\n    }\n\n    function App() {\n      const methods = useForm({\n        defaultValues: {\n          lastName: 'luo',\n        },\n      });\n      const {\n        formState: { dirtyFields },\n      } = methods;\n\n      return (\n        <FormProvider {...methods}>\n          <form>\n            <Form />\n            {dirtyFields.lastName ? 'dirty' : 'pristine'}\n          </form>\n        </FormProvider>\n      );\n    }\n\n    render(<App />, { reactStrictMode: true });\n\n    fireEvent.change(screen.getByRole('textbox'), {\n      target: {\n        value: 'luo1',\n      },\n    });\n\n    screen.getByText('dirty');\n\n    fireEvent.change(screen.getByRole('textbox'), {\n      target: {\n        value: 'luo',\n      },\n    });\n\n    screen.getByText('pristine');\n  });\n\n  it('should disable the controller input', async () => {\n    function Form() {\n      const { field } = useController({\n        name: 'lastName',\n      });\n      return <p>{field.disabled ? 'disabled' : ''}</p>;\n    }\n\n    function App() {\n      const methods = useForm({\n        disabled: true,\n      });\n\n      return (\n        <FormProvider {...methods}>\n          <form>\n            <Form />\n          </form>\n        </FormProvider>\n      );\n    }\n\n    render(<App />);\n\n    await waitFor(() => {\n      screen.getByText('disabled');\n    });\n  });\n\n  it('should disable form input with disabled prop', async () => {\n    const App = () => {\n      const [disabled, setDisabled] = React.useState(false);\n      const { control, watch } = useForm({\n        defaultValues: {\n          test: 'test',\n        },\n      });\n      const {\n        field: { disabled: disabledProps },\n      } = useController({\n        control,\n        name: 'test',\n        disabled,\n      });\n\n      const input = watch('test');\n\n      return (\n        <form>\n          <p>{input}</p>\n          <button\n            onClick={() => {\n              setDisabled(!disabled);\n            }}\n            type={'button'}\n          >\n            toggle\n          </button>\n          <p>{disabledProps ? 'disable' : 'notDisabled'}</p>\n        </form>\n      );\n    };\n\n    render(<App />);\n\n    screen.getByText('test');\n    screen.getByText('notDisabled');\n\n    fireEvent.click(screen.getByRole('button'));\n\n    waitFor(() => {\n      screen.getByText('');\n      screen.getByText('disable');\n    });\n  });\n\n  it('should disable form input field with disabled prop', async () => {\n    const App = () => {\n      const { control } = useForm();\n      const {\n        field,\n        fieldState: { invalid, isTouched, isDirty },\n      } = useController({\n        name: 'test',\n        control,\n        disabled: true,\n        rules: { required: true },\n      });\n\n      return (\n        <form>\n          <input {...field} />\n          <button>submit</button>\n          {invalid && <p>invalid</p>}\n          {isTouched && <p>isTouched</p>}\n          {isDirty && <p>isDirty</p>}\n        </form>\n      );\n    };\n\n    render(<App />);\n\n    await waitFor(() => {\n      expect(screen.getByRole('textbox')).toBeDisabled();\n    });\n  });\n\n  it('should not disable form input field with disabled=false', async () => {\n    const App = () => {\n      const { control } = useForm();\n      const {\n        field,\n        fieldState: { invalid, isTouched, isDirty },\n      } = useController({\n        name: 'test',\n        control,\n        disabled: false,\n        rules: { required: true },\n      });\n\n      return (\n        <form>\n          <input {...field} />\n          <button>submit</button>\n          {invalid && <p>invalid</p>}\n          {isTouched && <p>isTouched</p>}\n          {isDirty && <p>isDirty</p>}\n        </form>\n      );\n    };\n\n    render(<App />);\n\n    await waitFor(() => {\n      expect(screen.getByRole('textbox')).not.toBeDisabled();\n    });\n  });\n\n  it('should pass validation with disabled to set to true', () => {\n    const callback = jest.fn();\n\n    const App = () => {\n      const { handleSubmit, control } = useForm({\n        defaultValues: {\n          test: 'test',\n        },\n      });\n      const { field } = useController({\n        control,\n        rules: {\n          required: true,\n        },\n        name: 'test',\n        disabled: true,\n      });\n\n      return (\n        <form onSubmit={handleSubmit(callback)}>\n          <input {...field} />\n          <button>submit</button>\n        </form>\n      );\n    };\n\n    render(<App />);\n\n    fireEvent.click(screen.getByRole('button'));\n\n    waitFor(() => {\n      expect(callback).toHaveBeenCalled();\n    });\n  });\n\n  it('should not omit form value when disabled is